const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=[
{id:'s1',title:'初次拜访，打开客户心扉',category:'客户拜访',description:'从破冰到需求挖掘，让第一次沟通更有价值。',level:'入门',time:8,participants:1280,color:'',icon:'chat',persona:'陈经理',role:'成长型企业 · 人力资源负责人',style:'谨慎理性，注重实际价值',goals:['建立信任关系','挖掘业务需求','约定下一步行动'],opening:'你好，我只有十分钟。我们目前用的系统还算顺手，你们的方案能解决什么问题？'},
{id:'s2',title:'价格异议，如何守住价值',category:'异议处理',description:'面对「价格太高」，用价值回应客户的顾虑。',level:'进阶',time:12,participants:968,color:'blue',icon:'case',persona:'王总',role:'制造企业 · 采购负责人',style:'目标明确，对价格高度敏感',goals:['理解价格顾虑','量化产品价值','推动试点合作'],opening:'我看过你们的报价，比另外一家贵了 20%。如果价格不能调整，我们很难继续谈。'},
{id:'s3',title:'关键谈判，推动合作落地',category:'商务谈判',description:'识别决策链与关键诉求，促成双赢的合作。',level:'挑战',time:15,participants:756,color:'peach',icon:'award',persona:'林总',role:'连锁零售集团 · 业务副总裁',style:'强势务实，需要清晰的执行计划',goals:['识别决策条件','提出合作方案','明确落地时间'],opening:'你们的产品我们认可，但今年预算已经锁定。你打算怎么推进？'},
{id:'s4',title:'服务修复，重新赢得信任',category:'异议处理',description:'接住客户情绪，把一次投诉变成信任的转机。',level:'进阶',time:10,participants:624,color:'green',icon:'target',persona:'刘女士',role:'企业客户 · 项目负责人',style:'对交付失望，期待负责任的回应',goals:['共情客户情绪','澄清问题影响','给出跟进安排'],opening:'上次系统上线延误了三天，团队怨声载道。这次你们打算怎么保证？'},
{id:'s5',title:'需求访谈，找到真正的痛点',category:'客户拜访',description:'以开放式提问，区分表层诉求与真实需求。',level:'入门',time:8,participants:845,color:'blue',icon:'search',persona:'赵经理',role:'科技公司 · 培训经理',style:'乐于沟通，但需求还不明确',goals:['开放式提问','确认核心痛点','总结优先需求'],opening:'我们想给销售团队做培训，但过去上了很多课，好像都没什么效果。'},
{id:'s6',title:'续约沟通，让合作走得更远',category:'商务谈判',description:'用成果复盘与成长规划，开启下一阶段合作。',level:'挑战',time:12,participants:512,color:'',icon:'team',persona:'周总',role:'服务企业 · 运营总监',style:'看重结果，正在评估替代方案',goals:['回顾业务收益','应对续约顾虑','确认合作计划'],opening:'合同下个月到期。说实话，这一年我们没有感受到太大变化，为什么要续约？'}];
const baseReports=[{id:'r1',scenarioId:'s2',title:defaults[1].title,date:'2026-10-12 10:24',minutes:12,scores:[88,82,86,78,86],score:84,messages:[],seed:true},{id:'r2',scenarioId:'s1',title:defaults[0].title,date:'2026-10-11 15:36',minutes:8,scores:[94,89,92,86,89],score:90,messages:[],seed:true},{id:'r3',scenarioId:'s3',title:defaults[2].title,date:'2026-10-10 09:18',minutes:15,scores:[80,74,70,65,71],score:72,messages:[],seed:true}];
let saved={};try{saved=JSON.parse(localStorage.getItem('practice-studio-v1')||'{}')}catch{}
let scenarios=[...defaults,...(saved.scenarios||[])],reports=saved.reports||baseReports,target=saved.target||5,view='home',activeCategory='全部',searchText='',difficulty='全部难度',practice=null,selectedReport=null,lastFocus=null;
const views={home:'学习工作台',library:'陪练广场',scripts:'剧本工作室',reports:'练习报告',team:'团队看板'};
const dimensions=['沟通亲和力','需求洞察','价值表达','异议应对','行动推进'];
function persist(){try{localStorage.setItem('practice-studio-v1',JSON.stringify({scenarios:scenarios.filter(s=>s.custom),reports,target}))}catch{toast('当前浏览器无法保存数据，请导出报告留存')}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function go(next){if(practice&&view==='practice'&&next!=='practice'){if(!confirm('离开将结束本次未完成的练习，确定离开吗？'))return;practice=null}view=next;closeModal();render();window.scrollTo(0,0)}
function shell(content){return `<aside class="sidebar"><div class="brand"><div class="brandmark">✧</div><div>练境<small>PRACTICE STUDIO</small></div></div><div class="navlabel">个人学习</div>${nav('home','grid')}${nav('library','chat')}${nav('reports','chart')}<div class="navsep"></div><div class="navlabel">培训管理</div>${nav('scripts','file')}${nav('team','team')}<div class="sidebar-bottom"><div class="guide"><h3>每一次练习，都离优秀更近</h3><p>把方法变成习惯，<br>让成长发生在每一次对话里。</p><button onclick="showGuide()">了解如何开始 ${icon('arrow','icon-mini')}</button></div><div class="account"><div class="avatar">之</div><div><strong>李先之</strong><small>销售一部 · 演示账号</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="row"><button class="icon-btn mobile-toggle" aria-label="展开导航" onclick="$('.sidebar').classList.toggle('open')">${icon('menu')}</button><div class="breadcrumb">成长中心 <span>/ &nbsp; ${views[view]|| (view==='practice'?'沉浸陪练':'能力复盘')}</span></div></div><div class="top-actions"><span class="demo-label">交互演示版</span><button class="icon-btn" aria-label="查看通知" onclick="showNotifications()">${icon('bell')}</button><span class="workspace">星河科技 · 学习空间</span><div class="avatar" style="width:29px;height:29px;font-size:10px">之</div></div></header><main class="main">${content}<p class="footer-note">练境 Practice Studio · 基于公开产品介绍设计的独立原型，非北森官方产品<br>对话与评分为本地规则模拟 · 全部人物与团队数据均为演示数据</p></main></div>`}
function nav(id,i){return `<button class="navbtn ${view===id?'active':''}" ${view===id?'aria-current="page"':''} onclick="go('${id}')">${icon(i)}${views[id]}${id==='library'?'<span class="count">'+scenarios.length+'</span>':''}</button>`}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="row">${actions}</div></div>`}
function metric(label,value,unit,ico,foot){return `<div class="metric"><div class="metric-icon">${icon(ico)}</div><div><div class="metric-label">${label}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div></div>`}
function stats(){let total=reports.reduce((a,r)=>a+r.minutes,0);return `<div class="metrics">${metric('累计完成练习',reports.length,'次','chat','<em>↗</em> 每一次尝试，都算成长')}${metric('累计练习时长',total,'分钟','clock','专注练习，让进步有迹可循')}${metric('平均能力得分',Math.round(reports.reduce((a,r)=>a+r.score,0)/Math.max(1,reports.length)),'分','award','满分 100 · 演示评估')}${metric('本周目标进度',Math.min(reports.length,target)+' / '+target,'次','target',`<em>${Math.min(100,Math.round(reports.length/target*100))}%</em> 已完成本周练习目标`)}</div>`}
function card(s){return `<article class="scenario"><div class="scenario-cover ${s.color}"><div class="scene-art">${icon(s.icon)}</div><span class="level">${s.level}</span></div><div class="scenario-body"><h3>${escapeHTML(s.title)}</h3><p>${escapeHTML(s.description)}</p><div class="tags"><span class="tag">${s.category}</span><span class="tag">${s.time} 分钟</span>${s.custom?'<span class="tag">自建剧本</span>':''}</div><div class="card-footer"><span>${s.participants.toLocaleString()} 人已练习</span><button onclick="showScenario('${s.id}')">开始练习 →</button></div></div></article>`}
function recentTable(items){return `<div class="table-wrap"><table><thead><tr><th>练习场景</th><th>完成时间</th><th>综合得分</th><th>状态</th><th>操作</th></tr></thead><tbody>${items.map(r=>`<tr><td><strong>${escapeHTML(r.title)}</strong></td><td>${r.date}</td><td><span class="score">${r.score}</span> <small>分</small></td><td><span class="status ${r.score<80?'orange':''}">${r.score>=80?'已达标':'待提升'}</span></td><td><button class="table-action" onclick="openReport('${r.id}')">查看报告 ↗</button></td></tr>`).join('')}</tbody></table></div>`}
function categories(){return `<div class="tabs" role="tablist">${['全部','客户拜访','异议处理','商务谈判'].map(c=>`<button class="tab ${activeCategory===c?'active':''}" role="tab" aria-selected="${activeCategory===c}" onclick="activeCategory='${c}';render()">${c==='全部'?'为你推荐':c}</button>`).join('')}</div>`}
function filtered(){return scenarios.filter(s=>(activeCategory==='全部'||s.category===activeCategory)&&(difficulty==='全部难度'||s.level===difficulty)&&(!searchText||[s.title,s.description,s.category].join(' ').includes(searchText)))}
function home(){return heading('下午好，李先之 ☀','今天的每一次练习，都是明天从容表达的底气。',`<button class="secondary" onclick="go('reports')">${icon('chart')}成长报告</button><button class="primary" onclick="showScenario('s2')">${icon('play')}开始今日练习</button>`)+`<section class="hero"><div class="eyebrow">YOUR NEXT LEVEL STARTS HERE</div><h2>把每一次对话，练成你的主场</h2><p>真实业务场景 × AI 角色对练 × 个性化复盘<br>从「知道怎么说」到「自然说得好」。</p><button class="primary" onclick="go('library')">探索陪练场景 ${icon('arrow')}</button><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orb"></div><div class="orbit two"></div><span class="float-chip a">✧ 专属成长路径</span><span class="float-chip b">✓ 每一步进步，都看得见</span><span class="float-star">✦</span><span class="float-dot"></span></div></section>`+stats()+`<div class="dashboard-grid"><div><div class="section-head"><h2>精选陪练场景 <span class="pill">贴近你的业务</span></h2><button class="ghost" onclick="go('library')">查看全部 ${icon('chevron','icon-mini')}</button></div>${categories()}<div class="scenario-grid">${filtered().slice(0,3).map(card).join('')}</div><section class="recent"><div class="section-head"><h2>最近练习</h2><button class="ghost" onclick="go('reports')">全部记录 ${icon('chevron','icon-mini')}</button></div>${recentTable(reports.slice(0,3))}</section></div><aside class="dashboard-aside"><section class="panel progress-panel"><div class="section-head" style="margin:0"><h3>本周成长计划</h3><span class="pill">第 42 周</span></div><p class="panel-sub">保持节奏，进步就会发生</p><div class="ring" style="--progress:${Math.min(100,reports.length/target*100)}%"><div class="ring-inner"><strong>${Math.min(100,Math.round(reports.length/target*100))}<small>%</small></strong><p>本周目标已完成</p></div></div><div class="progress-detail"><span>练习目标 <strong>${target} 次</strong></span><span>已完成 <strong>${reports.length} 次</strong></span></div><button class="secondary" onclick="editTarget()">调整我的目标</button></section><section class="panel tip-panel"><div class="tip-icon">${icon('light')}</div><h3>今日练习锦囊</h3><p>客户说「太贵了」，不一定是在拒绝。先理解价格背后的顾虑，再让价值被看见。</p><button class="ghost" onclick="showKnowledge()">学习「价值回应法」 →</button></section></aside></div>`}
function library(){return heading('陪练广场','把真实挑战带进练习室，找到适合你的下一场对话。',`<button class="primary" onclick="openScript()">${icon('plus')}创建练习场景</button>`)+`<div class="library"><div class="filters"><label class="search">${icon('search')}<input aria-label="搜索陪练场景" placeholder="搜索场景、技能或关键词" value="${escapeHTML(searchText)}" oninput="searchText=this.value;updateCards()"></label><select aria-label="筛选难度" onchange="difficulty=this.value;updateCards()">${['全部难度','入门','进阶','挑战'].map(v=>`<option ${difficulty===v?'selected':''}>${v}</option>`).join('')}</select></div>${categories()}<div class="scenario-grid" id="libraryCards">${filtered().map(card).join('')||'<div class="empty">没有找到匹配场景，试试其他关键词。</div>'}</div></div>`}
function updateCards(){$('#libraryCards').innerHTML=filtered().map(card).join('')||'<div class="empty">没有找到匹配场景，试试其他关键词。</div>'}
function scripts(){return heading('剧本工作室','把业务经验变成可重复练习的场景。',`<button class="primary" onclick="openScript()">${icon('plus')}新建剧本</button>`)+`<div class="notice">演示工作流：输入业务资料 → 配置客户画像 → 设置训练目标 → 生成可练习剧本。内容生成采用本地模板，不会上传资料。</div><div class="script-list">${scenarios.map(s=>`<article class="panel script-card"><div class="metric-icon">${icon('file')}</div><div><h3>${escapeHTML(s.title)}</h3><p>${escapeHTML(s.persona)} · ${escapeHTML(s.style)}</p><span class="mini-badge">${s.custom?'我的剧本':'示例模板'}</span><div class="row"><button class="ghost" onclick="openScript('${s.id}')">${s.custom?'编辑剧本':'使用此模板'}</button><span style="color:#e1d7e7">｜</span><button class="ghost" onclick="showScenario('${s.id}')">预览并试练 →</button></div></div></article>`).join('')}</div>`}
function reportsPage(){return heading('练习报告','复盘每一次对话，把反馈变成下一次练习的方向。',`<button class="secondary" onclick="exportReports()">${icon('download')}导出记录</button>`)+stats()+`<div class="section-head"><h2>全部练习记录 <span class="pill">${reports.length} 份报告</span></h2></div>${recentTable(reports)}`}
let teamFilter='全部部门';const members=[{name:'李先之',dept:'销售一部',score:84,count:12},{name:'周宁',dept:'销售一部',score:92,count:18},{name:'苏雨',dept:'销售二部',score:89,count:16},{name:'许晨',dept:'销售二部',score:81,count:11},{name:'陈安',dept:'客户成功部',score:86,count:14},{name:'王可',dept:'客户成功部',score:76,count:9}];
function team(){let rows=members.filter(m=>teamFilter==='全部部门'||m.dept===teamFilter).map(m=>m.name==='李先之'?{...m,score:Math.round(reports.reduce((a,r)=>a+r.score,0)/reports.length),count:reports.length}:m).sort((a,b)=>b.score-a.score);return heading('团队能力看板','让能力被看见，让培训投入转化为持续成长。',`<button class="secondary" onclick="exportTeam()">${icon('download')}导出看板</button>`)+`<div class="filters"><select aria-label="筛选团队部门" onchange="teamFilter=this.value;render()">${['全部部门','销售一部','销售二部','客户成功部'].map(d=>`<option ${d===teamFilter?'selected':''}>${d}</option>`).join('')}</select><span class="demo-label">2026 年 10 月 · 演示数据</span></div><div class="metrics">${metric('参与练习人数',rows.length,'人','team','当前部门范围')}${metric('累计练习次数',rows.reduce((a,m)=>a+m.count,0),'次','chat','含演示账号新增练习')}${metric('团队平均能力',Math.round(rows.reduce((a,m)=>a+m.score,0)/rows.length),'分','award','按成员平均分计算')}${metric('能力达标率',Math.round(rows.filter(m=>m.score>=80).length/rows.length*100),'%','target','达标线为 80 分')}</div><div class="team-grid"><section class="panel"><h3>成员能力分布</h3><p class="panel-sub">满分 100 分 · 让进步有迹可循</p><div class="chart">${rows.map(m=>`<div class="chart-column"><span>${m.score}</span><div class="chart-bar" style="height:${m.score*1.4}px"></div><span>${m.name}</span></div>`).join('')}</div></section><section class="panel"><h3>成长排行榜</h3>${rows.slice(0,3).map((m,i)=>`<div class="rank-row"><span class="rank-num">0${i+1}</span><div class="avatar">${m.name.slice(-1)}</div><div><strong>${m.name}</strong><small>${m.dept} · 练习 ${m.count} 次</small></div><span class="score">${m.score}<small> 分</small></span></div>`).join('')}</section></div><div class="section-head"><h2>成员练习明细</h2><span class="subtitle">数据仅保存在当前浏览器</span></div><div class="table-wrap"><table><thead><tr><th>成员</th><th>所属部门</th><th>练习次数</th><th>能力得分</th><th>训练建议</th></tr></thead><tbody>${rows.map(m=>`<tr><td><strong>${m.name}</strong></td><td>${m.dept}</td><td>${m.count}</td><td><span class="score">${m.score}</span></td><td>${m.score>=85?'挑战商务谈判，拓宽能力边界':'加强需求提问与异议回应'}</td></tr>`).join('')}</tbody></table></div>`}
function render(){$('#app').innerHTML=shell(view==='home'?home():view==='library'?library():view==='scripts'?scripts():view==='reports'?reportsPage():view==='team'?team():view==='practice'?practicePage():reportPage());if(view==='practice')scrollChat()}
function modal(title,content,wide=false){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><div class="modal-header"><h2>${title}</h2><button class="icon-btn" aria-label="关闭对话框" onclick="closeModal()">${icon('close')}</button></div>${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay input, #overlay button')?.focus(),30)}
function closeModal(){$('#overlay').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
document.addEventListener('keydown',e=>{if(!$('#overlay .modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
function showScenario(id){const s=scenarios.find(s=>s.id===id);modal('准备好，开始一场真实对话',`<div class="scenario-cover ${s.color}" style="height:100px;border-radius:9px;margin-bottom:18px"><div class="scene-art">${icon(s.icon)}</div><span class="level">${s.level} · ${s.time} 分钟</span></div><h3 style="font-size:18px">${escapeHTML(s.title)}</h3><p class="description" style="margin-top:10px">${escapeHTML(s.description)}</p><div class="detail-persona"><div class="avatar">${escapeHTML(s.persona.slice(0,1))}</div><div><strong>${escapeHTML(s.persona)} · ${escapeHTML(s.role)}</strong><p>${escapeHTML(s.style)}</p></div></div><h3>本次训练目标</h3><ul class="goal-list">${s.goals.map(g=>`<li>${escapeHTML(g)}</li>`).join('')}</ul><div class="notice">文字对练 · 建议完成至少 3 轮沟通。模拟客户根据表达中的提问、价值和行动要素回应；报告采用演示评分。</div><div class="modal-footer"><button class="secondary" onclick="closeModal()">稍后再练</button><button class="primary" onclick="startPractice('${id}')">进入练习室 ${icon('arrow')}</button></div>`)}
function startPractice(id){closeModal();practice={scenario:scenarios.find(s=>s.id===id),messages:[],started:Date.now(),busy:false};practice.messages.push({role:'ai',text:practice.scenario.opening});view='practice';render();$('#reply')?.focus()}
function detected(){let t=(practice?.messages||[]).filter(m=>m.role==='user').map(m=>m.text).join(' ');return {empathy:/理解|了解|感谢|抱歉|确实|担心|认同|您好|你好/.test(t),needs:/[？?]|目前|什么|哪些|如何|请问|能否|方便|原因|痛点/.test(t),value:/提升|节省|降低|效果|价值|效率|收益|案例|百分|%|成本|数据/.test(t),objection:/预算|价格|贵|顾虑|担心|风险|试点|分期|保障|保证/.test(t),action:/下周|明天|安排|邀请|试用|试点|下一步|会议|演示|时间|周[一二三四五六日]|复盘/.test(t)}}
function practicePage(){const s=practice.scenario,d=detected(),n=practice.messages.filter(m=>m.role==='user').length;return heading('沉浸陪练',`${escapeHTML(s.title)} · 每一次表达，都是一次成长。`,`<button class="secondary" onclick="go('library')">退出练习</button><button class="primary" onclick="finishPractice()" ${n===0||practice.busy?'disabled':''}>结束并生成报告 ${icon('arrow')}</button>`)+`<div class="practice-layout"><aside class="panel persona-panel"><span class="demo-label">模拟客户</span><div class="portrait">${escapeHTML(s.persona.slice(0,1))}</div><h3>${escapeHTML(s.persona)}</h3><p>${escapeHTML(s.role)}</p><div class="tags"><span class="tag">${escapeHTML(s.style)}</span></div><div class="persona-goals"><h3>沟通要素提示</h3>${[['empathy','建立信任与共情'],['needs','探寻客户真实需求'],['value','表达可验证的价值'],['action','约定具体下一步']].map(([k,t])=>`<div class="goal-item ${d[k]?'done':''}"><span class="goal-dot">${d[k]?'✓':''}</span>${t}</div>`).join('')}<p style="font-size:10px;margin-top:22px">根据关键词检测，仅作练习提示。<br>已完成 ${n} 轮对话</p></div></aside><section class="panel conversation"><div class="chat-header"><div class="row">${icon('chat')}<strong>与 ${escapeHTML(s.persona)} 对话</strong></div><span class="live">本地模拟 · 文字陪练</span></div><div class="chat-messages" id="chatMessages">${practice.messages.map(m=>messageHTML(m,s)).join('')}${practice.busy?'<div class="message"><div class="avatar">…</div><div class="bubble">对方正在思考…</div></div>':''}</div><div class="chat-hint">✧ 教练提示：${coachHint(d,n)}</div><form class="composer" onsubmit="event.preventDefault();sendReply()"><textarea id="reply" aria-label="输入你的回复" maxlength="1200" placeholder="试着用你的方式回应客户…" ${practice.busy?'disabled':''} onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendReply()}"></textarea><div class="composer-bottom"><span>Enter 发送 · Shift + Enter 换行</span><button class="primary" type="submit" ${practice.busy?'disabled':''}>发送 ${icon('send')}</button></div></form></section></div>`}
function messageHTML(m,s){return `<div class="message ${m.role==='user'?'self':''}"><div class="avatar">${m.role==='user'?'之':escapeHTML(s.persona.slice(0,1))}</div><div class="bubble-wrap"><div class="message-label">${m.role==='user'?'我':escapeHTML(s.persona)}</div><div class="bubble">${escapeHTML(m.text)}</div></div></div>`}
function coachHint(d,n){return !n?'先接住对方的情绪，再用一个开放式问题了解背景。':!d.needs?'试着问一个具体问题，了解客户当前最需要解决的事情。':!d.value?'把功能转化为业务价值，用一个可衡量的结果来表达。':!d.action?'给出具体、低风险的下一步，让对话真正向前推进。':'很好，你覆盖了关键沟通要素。试着确认双方的理解是否一致。'}
function replyFor(text,n){const d=detected(),s=practice.scenario;if(text.length<8)return '可以再具体一些吗？我希望听到与你们方案相关、能帮助我们解决问题的内容。';if(d.action&&n>=3)return `可以。请把你提到的下一步计划发给我，包含目标、负责人和时间安排。我会邀请相关同事一起评估，先验证效果再决定。`;if(/[？?]|请问|哪些|什么|能否/.test(text)){if(s.category==='异议处理')return '我主要担心投入后看不到效果，还会增加团队的工作量。我们需要能量化的结果，以及一个风险可控的开始方式。';if(s.category==='商务谈判')return '最终需要业务和财务共同同意。我关注的是三个月内能看到什么变化，以及你们如何配合落地。';return '现在最头疼的是新人上手慢，培训完还是不敢跟客户聊。我们有三十多名销售，管理者也没有时间逐个陪练。'}if(d.value&&n>=2)return '这个方向我理解了，但这些收益具体怎么验证？有没有类似团队的落地方式？我们也不能一下投入太多资源。';if(d.empathy&&n===1)return '谢谢你理解。对我来说，方案是否适合我们的团队比功能多少更重要。你想先了解哪些情况？';if(n>=4)return '还有一个问题：如果试点没有达到预期，你们会怎么调整？我希望双方提前把评估标准说清楚。';return '你提到的我记下了。不过这些与我们现在的实际问题有什么关联？能结合一个具体场景说说吗？'}
function sendReply(){if(!practice||practice.busy)return;const t=$('#reply').value.trim();if(!t)return;practice.messages.push({role:'user',text:t});const n=practice.messages.filter(m=>m.role==='user').length;const response=replyFor(t,n);practice.busy=true;render();const current=practice;setTimeout(()=>{if(practice!==current)return;practice.messages.push({role:'ai',text:response});practice.busy=false;render();$('#reply')?.focus()},650)}
function scrollChat(){const el=$('#chatMessages');if(el)el.scrollTop=el.scrollHeight}
function finishPractice(){if(!practice||practice.busy)return;const n=practice.messages.filter(m=>m.role==='user').length;if(!n)return;const d=detected(),countBonus=Math.min(12,n*3),scores=Object.values(d).map(v=>Math.min(98,48+(v?34:0)+countBonus));const r={id:'r'+Date.now(),scenarioId:practice.scenario.id,title:practice.scenario.title,date:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date()),minutes:Math.max(1,Math.round((Date.now()-practice.started)/60000)),scores,score:Math.round(scores.reduce((a,b)=>a+b,0)/5),messages:practice.messages.map(m=>({...m})),detected:d,seed:false};reports.unshift(r);persist();practice=null;openReport(r.id);toast('练习报告已生成，并保存在当前浏览器')}
function openReport(id){selectedReport=reports.find(r=>r.id===id);view='result';closeModal();render();window.scrollTo(0,0)}
function radar(scores){const point=(i,r)=>[150+Math.sin(i*Math.PI*2/5)*r,130-Math.cos(i*Math.PI*2/5)*r];return `<svg class="radar" viewBox="0 0 300 270" role="img" aria-label="五项能力得分雷达图">${[.25,.5,.75,1].map(k=>`<polygon points="${[0,1,2,3,4].map(i=>point(i,85*k).join(',')).join(' ')}" fill="${k===1?'#fcfafe':'none'}" stroke="#e7deef"/>`).reverse().join('')}${[0,1,2,3,4].map(i=>`<line x1="150" y1="130" x2="${point(i,85)[0]}" y2="${point(i,85)[1]}" stroke="#ede5f3"/>`).join('')}<polygon points="${scores.map((s,i)=>point(i,s*.85).join(',')).join(' ')}" fill="#b193d83c" stroke="#b193d8" stroke-width="2"/>${dimensions.map((d,i)=>{const p=point(i,114);return `<text x="${p[0]}" y="${p[1]}" text-anchor="middle" font-size="10" fill="#a48caf">${d}</text>`}).join('')}</svg>`}
const suggestions=['先认可客户的处境，再展开产品介绍。','使用开放式问题，确认业务痛点与优先级。','将产品功能转化为可衡量的业务结果。','回应顾虑时，提出可验证、可调整的低风险方案。','用具体时间和行动安排结束对话。'];
function reportPage(){const r=selectedReport||reports[0],lowest=r.scores.indexOf(Math.min(...r.scores)),highest=r.scores.indexOf(Math.max(...r.scores));return heading('每一次复盘，都是进步的起点',`${escapeHTML(r.title)} · ${r.date}`,`<button class="secondary" onclick="exportOne('${r.id}')">${icon('download')}导出报告</button><button class="primary" onclick="showScenario('${r.scenarioId}')">再练一次 ${icon('arrow')}</button>`)+`<div class="notice">${r.seed?'此报告为预置示例，分数和建议仅供体验。':'本报告由本地关键词规则生成，不代表真实 AI 能力评估。'} 评分方式：每项基础分 48 分，覆盖对应表达要素加 34 分，每轮对话加 3 分（最多加 12 分）。</div><div class="panel report-summary"><div class="result-score"><small>本次综合得分</small><strong>${r.score}<span style="font-size:17px"> / 100</span></strong><span class="status ${r.score<80?'orange':''}">${r.score>=80?'本次练习已达标':'继续练习，稳步提升'}</span></div><div class="result-text"><h3>${r.score>=80?'表达更有方向，沟通更有力量':'找到突破点，让下一次更从容'}</h3><p>${highest===lowest?'本次各项得分相同。可以挑战新场景，进一步练习具体表达。':`本次练习中，「${dimensions[highest]}」是你的优势。<br>下一次重点关注「${dimensions[lowest]}」：${suggestions[lowest]}`}</p><div class="goal-tags"><span class="tag">练习 ${r.minutes} 分钟</span><span class="tag">${r.seed?'示例报告':r.messages.filter(m=>m.role==='user').length+' 轮对话'}</span><span class="tag">达标线 80 分</span></div><button class="ghost" onclick="showKnowledge()">查看表达工具箱 →</button></div></div><div class="report-columns"><section class="panel"><h3>你的能力画像</h3>${radar(r.scores)}${dimensions.map((d,i)=>`<div class="dimension"><div class="dimension-head"><span>${d}</span><span>${r.scores[i]} 分</span></div><div class="bar"><div style="width:${r.scores[i]}%"></div></div></div>`).join('')}</section><section class="panel"><h3>对话复盘与改进建议</h3><p class="panel-sub">让每一条反馈，都能用在下一次对话里</p>${r.messages.filter(m=>m.role==='user').slice(0,6).map((m,i)=>`<div class="feedback-item"><small>第 ${i+1} 轮 · 我的表达</small><p>“${escapeHTML(m.text)}”</p><blockquote>${suggestions[i%5]}</blockquote></div>`).join('')||suggestions.slice(0,3).map((s,i)=>`<div class="feedback-item"><small>改进方向 0${i+1}</small><p>${s}</p><blockquote>${['“我理解你对投入产出的关注，方便说说目前最想改善的环节吗？”','“如果先选一个团队试点，我们可以一起观察新人独立沟通所需的时间。”','“不如约在下周三，一起明确试点目标、范围和评估方式。”'][i]}</blockquote></div>`).join('')}</section></div><div class="row" style="justify-content:center;margin-top:25px"><button class="secondary" onclick="go('reports')">返回全部报告</button></div>`}
function openScript(id){const s=scenarios.find(s=>s.id===id);modal(s?.custom?'编辑陪练剧本':'创建你的陪练剧本',`<form id="scriptForm" onsubmit="event.preventDefault();saveScript('${s?.custom?s.id:''}')"><div class="steps"><span class="step-active">01 业务背景</span><span>→</span><span>02 客户画像</span><span>→</span><span>03 生成场景</span></div><div class="form-grid"><label class="field full">剧本名称<input name="title" required maxlength="32" placeholder="例如：企业软件首次需求访谈" value="${escapeHTML(s?.title||'')}"></label><label class="field">业务场景<select name="category">${['客户拜访','异议处理','商务谈判'].map(c=>`<option ${s?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">练习难度<select name="level">${['入门','进阶','挑战'].map(c=>`<option ${s?.level===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">客户称呼<input name="persona" required maxlength="15" value="${escapeHTML(s?.persona||'张经理')}"></label><label class="field">客户角色<input name="role" required maxlength="50" value="${escapeHTML(s?.role||'企业客户 · 业务负责人')}"></label><label class="field full">客户性格与沟通偏好<input name="style" required maxlength="80" value="${escapeHTML(s?.style||'理性谨慎，关注实际效果')}"></label><label class="field full">业务资料 / 产品卖点<textarea id="sourceText" name="source" required maxlength="5000" placeholder="输入产品介绍、典型客户问题或希望练习的业务背景。">${escapeHTML(s?.source||s?.description||'')}</textarea><small>也可导入 TXT 文件（最大 100KB），仅在当前浏览器处理。</small><input aria-label="导入业务资料 TXT" type="file" accept=".txt,text/plain" onchange="importText(this)"></label><label class="field full">训练目标（每行一个，最多 5 项）<textarea name="goals" required maxlength="500">${escapeHTML((s?.goals||['挖掘客户真实需求','清晰表达业务价值','约定具体下一步']).join('\n'))}</textarea></label><label class="field full">客户开场白<input name="opening" required maxlength="250" value="${escapeHTML(s?.opening||'你好，我们正在了解不同的方案。你能先说说，你们能解决什么具体问题吗？')}"></label></div><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary" type="submit">${icon('spark')}${s?.custom?'保存修改':'生成陪练剧本'}</button></div><p class="subtitle">演示版将按你的配置生成模板剧本，不调用大模型。</p></form>`,true)}
function importText(input){const f=input.files[0];if(!f)return;if(f.size>102400){toast('请选择小于 100KB 的 TXT 文件');input.value='';return}if(!f.name.toLowerCase().endsWith('.txt')){toast('目前仅支持 TXT 文本文件');return}f.text().then(t=>{$('#sourceText').value=t.slice(0,5000);toast('业务资料已导入')})}
function saveScript(id){const f=new FormData($('#scriptForm'));const val=k=>String(f.get(k)||'').trim();const goals=val('goals').split('\n').map(t=>t.trim()).filter(Boolean).slice(0,5);if(!val('title')||!goals.length||!val('source')){toast('请填写剧本名称、业务资料和训练目标');return}const s={id:id||'s'+Date.now(),title:val('title'),category:val('category'),level:val('level'),persona:val('persona'),role:val('role'),style:val('style'),description:val('source').slice(0,70),source:val('source'),goals,opening:val('opening'),time:10,participants:0,color:'green',icon:'file',custom:true};const i=scenarios.findIndex(x=>x.id===id);if(i>=0)scenarios[i]=s;else scenarios.push(s);persist();closeModal();view='scripts';render();toast(id?'剧本已更新':'剧本已生成，可以开始试练')}
function editTarget(){modal('设定你的本周练习目标',`<p class="description">小步前进，持续成长。每周完成 3–5 次练习，是一个不错的开始。</p><form onsubmit="event.preventDefault();target=Number($('#targetValue').value);persist();closeModal();render();toast('本周目标已更新')"><label class="field">每周练习次数<input id="targetValue" type="number" min="1" max="30" value="${target}" required></label><div class="modal-footer"><button class="primary">保存目标</button></div></form>`)}
function showGuide(){modal('欢迎来到练境',`<p class="description">用一次完整练习，体验从学习到实战的闭环。</p><div class="intro-list"><div><h3>01 选择你的挑战</h3><p>进入陪练广场，选择客户拜访、异议处理或商务谈判。</p></div><div><h3>02 开始角色对练</h3><p>了解客户画像，用文字展开沟通。建议至少完成 3 轮。</p></div><div><h3>03 查看能力复盘</h3><p>结束后生成评分与表达建议，也可以导出完整对话。</p></div><div><h3>04 创建专属剧本</h3><p>把业务资料和训练目标转化为自己的练习场景。</p></div></div><div class="notice" style="margin:20px 0 0">这是基于北森 AI 陪练公开介绍设计的独立交互原型。采用演示数据与本地规则；不含真人数字人、语音识别、真实 AI 推理和企业账号服务。数据仅保存在当前浏览器。</div><div class="modal-footer"><button class="primary" onclick="go('library')">开始探索 ${icon('arrow')}</button></div>`)}
function showKnowledge(){modal('表达工具箱 · 价值回应法',`<p class="description">面对客户异议，先理解，再把价值说具体。</p>${[['接住顾虑','我理解您对投入产出的关注。我们先确认一下，您最担心的是预算压力，还是效果不确定？'],['连接业务价值','相比单纯增加培训次数，我们可以一起观察：新人独立完成客户沟通的时间，是否能够缩短。'],['设计低风险验证','建议先选择一个小团队做试点，提前约定评估标准，再决定是否扩大范围。'],['约定下一步','下周三是否方便？我准备一份试点计划，我们一起确认人员、周期和目标。']].map(([h,p])=>`<div class="knowledge-item"><h3>${h}</h3><p>${p}</p></div>`).join('')}<div class="modal-footer"><button class="primary" onclick="showScenario('s2')">把方法用在练习中 ${icon('arrow')}</button></div>`)}
function showNotifications(){modal('学习动态',`<div class="knowledge-item"><h3>你的成长计划正在进行</h3><p>本周已经完成 ${reports.length} 次练习，目标 ${target} 次。${reports.length>=target?'目标已达成，继续挑战新场景吧。':'选择一个场景，开始今天的练习。'}</p></div><div class="knowledge-item"><h3>欢迎体验陪练原型</h3><p>所有场景都可以开始文字对练，结束后会自动生成能力报告。</p></div><div class="modal-footer"><button class="primary" onclick="go('library')">查看练习场景</button></div>`)}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([type.includes('csv')?'\ufeff':'',text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('导出文件已生成')}
function exportOne(id){download('练境-练习报告-'+id+'.json',JSON.stringify({notice:'演示评分，仅供原型体验',...reports.find(r=>r.id===id)},null,2))}
function csvCell(v){let s=String(v);if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportReports(){download('练境-练习记录.csv',[['练习场景','完成时间','练习分钟','综合得分','报告类型'],...reports.map(r=>[r.title,r.date,r.minutes,r.score,r.seed?'预置演示':'本地模拟'])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function exportTeam(){const rows=members.filter(m=>teamFilter==='全部部门'||m.dept===teamFilter).map(m=>m.name==='李先之'?{...m,score:Math.round(reports.reduce((a,r)=>a+r.score,0)/reports.length),count:reports.length}:m);download('练境-团队看板.csv',[['姓名','部门','练习次数','能力得分','数据类型'],...rows.map(m=>[m.name,m.dept,m.count,m.score,'演示数据'])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
window.addEventListener('beforeunload',e=>{if(practice&&practice.messages.length>1){e.preventDefault();e.returnValue=''}});
render();

if(window.parent!==window){document.body.classList.add('embedded');window.addEventListener('message',e=>{if(e.source===window.parent&&e.origin===location.origin&&e.data?.type==='prototype-coach-nav'&&Object.hasOwn(views,e.data.view))go(e.data.view)})}
